#!/usr/bin/env python3
"""Exercise production usage parsers and fetch lifecycle without account/network access."""
from pathlib import Path
import os
import subprocess
import tempfile

source = Path(__file__).resolve().parents[1] / 'ClaudeLiveDaemon.swift'
text = source.read_text()
a = text.index('struct AIUsageWindow:')
b = text.index('/// Read the shared Codex queue', a)
code = text[a:b].replace('private ', '')
a = code.index('    func credentials(')
b = code.index('    func fetch(', a)
code = code[:a] + '    func credentials(_ id: String, allowPrompt: Bool) -> (String, String?)? { ("test-token", nil) }\n' + code[b:]
code = code.replace('let config = URLSessionConfiguration.ephemeral', 'let config = URLSessionConfiguration.ephemeral\n        config.protocolClasses = [UsageStub.self]')
HARNESS = 'import Foundation\nfinal class UsageStub: URLProtocol, @unchecked Sendable {\n    static let lock = NSLock()\n    nonisolated(unsafe) static var counts: [String: Int] = [:]\n    nonisolated(unsafe) static var code = 200\n    override class func canInit(with request: URLRequest) -> Bool { true }\n    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }\n    override func startLoading() {\n        let provider = request.url!.host!.contains("anthropic") ? "claude" : "codex"\n        Self.lock.lock(); Self.counts[provider, default: 0] += 1; let status = Self.code; Self.lock.unlock()\n        let json = provider == "claude" ? #"{"five_hour":{"utilization":23,"resets_at":"2026-10-17T00:00:00Z"}}"# : #"{"rate_limit":{"secondary_window":{"used_percent":44,"limit_window_seconds":604800,"reset_at":1792195200}}}"#\n        client?.urlProtocol(self, didReceive: HTTPURLResponse(url: request.url!, statusCode: status, httpVersion: nil, headerFields: ["Retry-After":"600"])!, cacheStoragePolicy: .notAllowed)\n        client?.urlProtocol(self, didLoad: Data(json.utf8)); client?.urlProtocolDidFinishLoading(self)\n    }\n    override func stopLoading() {}\n}\n@main struct Checks {\n    static func main() throws {\n        precondition(AIUsageParser.claude(["five_hour": ["utilization": NSNull()]]).isEmpty)\n        precondition(AIUsageParser.claude(["five_hour": ["utilization": true]]).isEmpty)\n        precondition(AIUsageParser.claude(["five_hour": ["utilization": 0]])[0].usedPercent == 0)\n        let scoped = AIUsageParser.claude(["limits": [["kind":"weekly_scoped", "percent":36, "scope":["model":["display_name":"Fable"]]]]])\n        precondition(scoped[0].title == "週間・Fable" && scoped[0].usedPercent == 36)\n        precondition(AIUsageParser.codex(["rate_limit":["primary_window":["used_percent":120,"limit_window_seconds":18000]]])[0].usedPercent == 100)\n        let monitor = AIUsageMonitor()\n        _ = monitor.snapshot()\n        func waitUntilFinished() {\n            for _ in 0..<200 {\n                let done = monitor.worker.sync { monitor.providers.values.allSatisfy { !$0.refreshing } }\n                if done { return }; Thread.sleep(forTimeInterval: 0.01)\n            }\n            preconditionFailure("request timed out")\n        }\n        // Ensure the request-scheduling closure has run before waiting.\n        monitor.worker.sync {}\n        waitUntilFinished()\n        monitor.worker.sync {\n            precondition(monitor.providers["claude"]!.windows[0].usedPercent == 23)\n            precondition(monitor.providers["codex"]!.windows[0].title == "週間")\n            monitor.nextFetch = [:]\n        }\n        UsageStub.lock.lock(); UsageStub.code = 429; UsageStub.lock.unlock()\n        _ = monitor.snapshot(); monitor.worker.sync {}; waitUntilFinished()\n        monitor.worker.sync {\n            precondition(monitor.providers["claude"]!.windows[0].usedPercent == 23)\n            precondition(monitor.providers["claude"]!.retryAt! > Date().timeIntervalSince1970 + 500)\n        }\n        UsageStub.lock.lock(); let before = UsageStub.counts; UsageStub.lock.unlock()\n        for _ in 0..<10 { _ = monitor.snapshot(refresh: true) }\n        monitor.worker.sync {}\n        UsageStub.lock.lock(); precondition(before == UsageStub.counts); UsageStub.lock.unlock()\n        monitor.worker.sync {\n            monitor.nextFetch = ["claude":Date.distantFuture, "codex":Date.distantFuture]\n            monitor.providers["claude"]!.windows = [\n                AIUsageWindow(id:"weekly_scoped-0", title:"週間・モデル別", usedPercent:90, resetsAt:Date().timeIntervalSince1970+1000),\n                AIUsageWindow(id:"weekly_all-1", title:"週間・全モデル", usedPercent:36, resetsAt:Date().timeIntervalSince1970+1000)]\n            monitor.providers["claude"]!.fetchedAt = Date().timeIntervalSince1970\n            monitor.providers["codex"]!.windows = [AIUsageWindow(id:"primary_window", title:"週間", usedPercent:43, resetsAt:Date().timeIntervalSince1970+1000)]\n            monitor.providers["codex"]!.fetchedAt = Date().timeIntervalSince1970\n            monitor.publish()\n        }\n        precondition(monitor.weeklyUsage(provider:"claude")?.percent == 36)\n        precondition(monitor.weeklyUsage(provider:"codex")?.percent == 43)\n        monitor.worker.sync {\n            monitor.providers["claude"]!.fetchedAt = Date().timeIntervalSince1970 - 1000\n            monitor.providers["codex"]!.windows = [AIUsageWindow(id:"primary_window", title:"週間", usedPercent:43, resetsAt:Date().timeIntervalSince1970-1)]\n            monitor.publish()\n        }\n        precondition(monitor.weeklyUsage(provider:"claude") == nil)\n        precondition(monitor.weeklyUsage(provider:"codex") == nil)\n        let snapshot = monitor.cachedSnapshot()\n        precondition(!snapshot.contains("test-token") && !snapshot.contains("Authorization"))\n        print("PASS: null is not zero, scoped models, window labels, percentage bounds, live decode, stale preservation, Retry-After/manual refresh backoff, credential-free snapshots")\n    }\n}\n'
with tempfile.TemporaryDirectory(prefix='notch-usage-tests-') as temp:
    root = Path(temp)
    (root / 'Monitor.swift').write_text('import Foundation\nimport CoreFoundation\n' + code)
    (root / 'Checks.swift').write_text(HARNESS)
    subprocess.run(['xcrun', 'swiftc', '-target', 'arm64-apple-macos14.0', str(root / 'Monitor.swift'), str(root / 'Checks.swift'), '-o', str(root / 'checks')], check=True)
    subprocess.run([str(root / 'checks')], check=True)
